/* From Uiverse.io by gharsh11032000 - Tags: gradient, card, hover, hover effect */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 190px;
  height: 254px;
  background-color: #000;
  display: flex;
  flex-direction: column;
  justify-content: end;
  padding: 12px;
  gap: 12px;
  border-radius: 8px;
  cursor: pointer;
}

.__UIV_SCOPE__ .card::before {
  content: '';
  position: absolute;
  inset: 0;
  left: -5px;
  margin: auto;
  width: 200px;
  height: 264px;
  border-radius: 10px;
  background: linear-gradient(-45deg, #e81cff 0%, #40c9ff 100% );
  z-index: -10;
  pointer-events: none;
  transition: all 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.__UIV_SCOPE__ .card::after {
  content: "";
  z-index: -1;
  position: absolute;
  inset: 0;
  background: linear-gradient(-45deg, #fc00ff 0%, #00dbde 100% );
  transform: translate3d(0, 0, 0) scale(0.95);
  filter: blur(20px);
}

.__UIV_SCOPE__ .heading {
  font-size: 20px;
  text-transform: capitalize;
  font-weight: 700;
}

.__UIV_SCOPE__ .card p:not(.heading) {
  font-size: 14px;
}

.__UIV_SCOPE__ .card p:last-child {
  color: #e81cff;
  font-weight: 600;
}

.__UIV_SCOPE__ .card:hover::after {
  filter: blur(30px);
}

.__UIV_SCOPE__ .card:hover::before {
  transform: rotate(-90deg) scaleX(1.34) scaleY(0.77);
}
